using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class ExportB5SurfaceAudit {static string P(Transform t)=>t.parent==null?t.name:P(t.parent)+"/"+t.name;public static string Main(){var records=new List<object>();int meshes=0;foreach(var f in SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true))){var rr=f.GetComponent<MeshRenderer>();if(!rr||!rr.enabled||!f.gameObject.activeInHierarchy||!f.sharedMesh)continue;string path=P(f.transform);bool generic=path.Contains("/Geometry/")&&(f.name.Contains("Wall")||f.name.Contains("Ceiling")||f.name.Contains("Floor"));bool rebuilt=path.Contains("/RebuiltArchitectureVisual/");if(!generic&&!rebuilt)continue;if(rr.sharedMaterials.Any(m=>m&&m.HasProperty("_Surface")&&m.GetFloat("_Surface")>0))continue;meshes++;var vv=f.sharedMesh.vertices.Select(v=>f.transform.TransformPoint(v)).ToArray();var tt=f.sharedMesh.triangles;for(int i=0;i<tt.Length;i+=3){var p=vv[tt[i]];var q=vv[tt[i+1]];var s=vv[tt[i+2]];var cross=Vector3.Cross(q-p,s-p);if(cross.magnitude*.5f<.005f)continue;var n=cross.normalized;int axis=Enumerable.Range(0,3).OrderByDescending(k=>Mathf.Abs(n[k])).First();if(Mathf.Abs(n[axis])<.99999f)continue;var axes=Enumerable.Range(0,3).Where(k=>k!=axis).ToArray();records.Add(new{path,axis,sign=n[axis]>0?1:-1,plane=(p[axis]+q[axis]+s[axis])/3,points=new[]{new[]{p[axes[0]],p[axes[1]]},new[]{q[axes[0]],q[axes[1]]},new[]{s[axes[0]],s[axes[1]]}}});}}string r=Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/B5_Clinical_Tone_20261103"));File.WriteAllText(r+"/architecture_triangles.json",JsonConvert.SerializeObject(records));return "Exported "+records.Count+" axial triangles from "+meshes+" architecture meshes";}}

